 3→/**
 4→ * Response DTO for vault export.
 5→ * Contains the minimal data needed for independent recovery:
 6→ * root IPNS name + encrypted root keys.
 7→ */
 8→export class VaultExportDto {
 9→  @ApiProperty({
10→    description: 'Export format identifier',
11→    example: 'cipherbox-vault-export',
12→  })
13→  format!: string;
14→
15→  @ApiProperty({
16→    description: 'Export format version',
17→    example: '1.0',
18→  })
19→  version!: string;
