21→  @ApiProperty({
22→    description: 'ISO 8601 timestamp of when the export was created',
23→    example: '2026-02-11T12:00:00.000Z',
24→  })
25→  exportedAt!: string;
26→
27→  @ApiProperty({
28→    description: 'IPNS name for the root folder (libp2p-key multihash)',
29→    example: 'k51qzi5uqu5dg...',
30→  })
31→  rootIpnsName!: string;
32→
33→  @ApiProperty({
34→    description: 'ECIES-wrapped root folder AES-256 key (hex-encoded)',
35→    example: 'a1b2c3d4e5f6...',
36→  })
37→  encryptedRootFolderKey!: string;
38→
39→  @ApiProperty({
40→    description: 'ECIES-wrapped Ed25519 IPNS private key (hex-encoded)',
41→    example: 'a1b2c3d4e5f6...',
42→  })
43→  encryptedRootIpnsPrivateKey!: string;
44→
45→  @ApiPropertyOptional({
46→    description:
47→      'Key derivation method used. Always "web3auth" for Core Kit users. Null if user record not found.',
48→    example: 'web3auth',
49→    nullable: true,
50→    type: String,
