 1→import { create } from 'zustand';
 2→
 3→type TeeKeys = {
 4→  currentEpoch: number;
 5→  currentPublicKey: string;
 6→  previousEpoch: number | null;
 7→  previousPublicKey: string | null;
 8→};
 9→
10→/**
11→ * User's secp256k1 vault keypair from Core Kit TSS export.
12→ * Memory-only, never persisted.
13→ */
14→type VaultKeypair = {
15→  publicKey: Uint8Array;
16→  privateKey: Uint8Array;
17→};
18→
19→type AuthState = {
20→  accessToken: string | null;
21→  isAuthenticated: boolean;
22→  lastAuthMethod: string | null;
23→  userEmail: string | null;
24→  teeKeys: TeeKeys | null;
25→
26→  /** User's vault keypair (memory-only, from Core Kit TSS export) */
27→  vaultKeypair: VaultKeypair | null;
28→
29→  /** Pending auth info for REQUIRED_SHARE flow (shared across hook instances) */
30→  pendingCipherboxJwt: string | null;
31→  pendingAuthMethod: string | null;
32→
33→  setAccessToken: (token: string) => void;
34→  setLastAuthMethod: (method: string) => void;
35→  setUserEmail: (email: string) => void;
36→  setTeeKeys: (keys: TeeKeys) => void;
37→  setVaultKeypair: (keypair: VaultKeypair) => void;
38→  setPendingAuth: (jwt: string | null, method: string | null) => void;
39→  logout: () => void;
40→};
41→
42→export const useAuthStore = create<AuthState>((set, get) => ({
43→  // State - stored in memory only, NOT localStorage (XSS prevention)
44→  accessToken: null,
45→  isAuthenticated: false,
46→  lastAuthMethod: null,
47→  userEmail: null,
48→  teeKeys: null,
49→
50→  /** User's vault keypair (memory-only) */
51→  vaultKeypair: null,
52→
53→  /** Pending auth for REQUIRED_SHARE flow */
54→  pendingCipherboxJwt: null,
55→  pendingAuthMethod: null,
56→
57→  // Actions
58→  setAccessToken: (token) => set({ accessToken: token, isAuthenticated: true }),
59→  setLastAuthMethod: (method) => set({ lastAuthMethod: method }),
60→  setUserEmail: (email) => set({ userEmail: email }),
61→  setTeeKeys: (keys) => set({ teeKeys: keys }),
62→
63→  /** Store vault keypair from Core Kit TSS export */
64→  setVaultKeypair: (keypair) => set({ vaultKeypair: keypair }),
65→
66→  /** Store pending auth info for REQUIRED_SHARE completion */
67→  setPendingAuth: (jwt, method) => set({ pendingCipherboxJwt: jwt, pendingAuthMethod: method }),
68→
69→  logout: () => {
70→    // [SECURITY: MEDIUM-02] Zero-fill sensitive key material before clearing
71→    const state = get();
72→    if (state.vaultKeypair) {
73→      if (state.vaultKeypair.privateKey) {
74→        state.vaultKeypair.privateKey.fill(0);
75→      }
76→      if (state.vaultKeypair.publicKey) {
77→        state.vaultKeypair.publicKey.fill(0);
78→      }
79→    }
80→
81→    set({
82→      accessToken: null,
83→      isAuthenticated: false,
84→      userEmail: null,
85→      teeKeys: null,
86→      vaultKeypair: null,
87→      pendingCipherboxJwt: null,
88→      pendingAuthMethod: null,
89→    });
90→  },
91→}));
