423→   423→    // =========================================================================
424→   424→    function hexToBytes(hex) {
425→   425→      const clean = hex.startsWith('0x') ? hex.slice(2) : hex;
426→   426→      if (clean.length % 2 !== 0) throw new Error('Invalid hex: odd length');
427→   427→      const bytes = new Uint8Array(clean.length / 2);
428→   428→      for (let i = 0; i < bytes.length; i++) {
429→   429→        const b = parseInt(clean.substring(i * 2, i * 2 + 2), 16);
430→   430→        if (Number.isNaN(b)) throw new Error('Invalid hex character');
431→   431→        bytes[i] = b;
432→   432→      }
433→   433→      return bytes;
434→   434→    }
435→   435→
436→   436→    function bytesToHex(bytes) {
437→   437→      return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
438→   438→    }
439→   439→
440→   440→    function base64ToBytes(b64) {
441→   441→      const bin = atob(b64);
442→   442→      const bytes = new Uint8Array(bin.length);
443→   443→      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
444→   444→      return bytes;
445→   445→    }
446→   446→
447→   447→    function truncate(str, len) {
448→   448→      if (str.length <= len) return str;
449→   449→      return str.slice(0, len) + '...';
450→   450→    }
