452→   452→    // =========================================================================
453→   453→    // Crypto: ECIES Decrypt (matches eciesjs@0.4.16 exactly)
454→   454→    // =========================================================================
455→   455→    async function eciesDecrypt(privKeyBytes, encryptedHex) {
456→   456→      const data = typeof encryptedHex === 'string' ? hexToBytes(encryptedHex) : encryptedHex;
457→   457→
458→   458→      // 1. Extract ephemeral public key (65 bytes, uncompressed, 0x04 prefix)
459→   459→      if (data.length < 65 + 16 + 16) {
460→   460→        throw new Error('ECIES ciphertext too short');
461→   461→      }
462→   462→      const ephemeralPK = data.slice(0, 65);
463→   463→      const payload = data.slice(65);
464→   464→
465→   465→      // 2. Compute ECDH shared point (uncompressed output)
466→   466→      //    eciesjs passes compressed ephemeral PK to getSharedSecret internally
467→   467→      //    but output is uncompressed (compressed=false)
468→   468→      const ephemeralPKCompressed = secp256k1.ProjectivePoint.fromHex(ephemeralPK).toRawBytes(true);
469→   469→      const sharedPoint = secp256k1.getSharedSecret(privKeyBytes, ephemeralPKCompressed, false);
470→   470→
471→   471→      // 3. senderPoint = ephemeral PK uncompressed (65 bytes)
472→   472→      const senderPoint = ephemeralPK;
473→   473→
474→   474→      // 4. Derive shared key: HKDF-SHA256(ikm=senderPoint||sharedPoint, salt=undefined, info=undefined, length=32)
475→   475→      const ikm = concatBytes(senderPoint, sharedPoint);
476→   476→      const sharedKey = hkdf(sha256, ikm, undefined, undefined, 32);
477→   477→
478→   478→      // 5. Extract nonce (16 bytes), tag (16 bytes), ciphertext
479→   479→      const nonce = payload.slice(0, 16);
480→   480→      const tag = payload.slice(16, 32);
481→   481→      const ciphertext = payload.slice(32);
482→   482→
483→   483→      // 6. Decrypt with AES-256-GCM
484→   484→      //    Web Crypto expects ciphertext||tag concatenated
485→   485→      const combined = new Uint8Array(ciphertext.length + tag.length);
486→   486→      combined.set(ciphertext, 0);
487→   487→      combined.set(tag, ciphertext.length);
488→   488→
489→   489→      const cryptoKey = await crypto.subtle.importKey(
490→   490→        'raw', sharedKey, { name: 'AES-GCM' }, false, ['decrypt']
491→   491→      );
492→   492→      const plaintext = await crypto.subtle.decrypt(
493→   493→        { name: 'AES-GCM', iv: nonce }, cryptoKey, combined
494→   494→      );
495→   495→
496→   496→      return new Uint8Array(plaintext);
497→   497→    }
498→   498→
499→   499→    // =========================================================================
500→   500→    // Crypto: AES-256-GCM Folder Metadata Decrypt
501→   501→    // =========================================================================
502→   502→    async function decryptFolderMetadata(encryptedJson, folderKey) {
503→   503→      // encryptedJson = { iv: "hex", data: "base64" }
504→   504→      const iv = hexToBytes(encryptedJson.iv);       // 12 bytes
505→   505→      const ciphertext = base64ToBytes(encryptedJson.data); // includes 16-byte auth tag
506→   506→
507→   507→      const cryptoKey = await crypto.subtle.importKey(
508→   508→        'raw', folderKey, { name: 'AES-GCM' }, false, ['decrypt']
509→   509→      );
510→   510→      const plaintext = await crypto.subtle.decrypt(
511→   511→        { name: 'AES-GCM', iv }, cryptoKey, ciphertext
512→   512→      );
513→   513→
514→   514→      return JSON.parse(new TextDecoder().decode(plaintext));
515→   515→    }
516→   516→
517→   517→    // =========================================================================
518→   518→    // Crypto: AES-256-GCM File Decrypt
519→   519→    // =========================================================================
520→   520→    async function decryptFileGcm(encryptedBytes, fileKey, fileIvHex) {
521→   521→      const iv = hexToBytes(fileIvHex); // 12 bytes
522→   522→
523→   523→      const cryptoKey = await crypto.subtle.importKey(
524→   524→        'raw', fileKey, { name: 'AES-GCM' }, false, ['decrypt']
525→   525→      );
526→   526→      const plaintext = await crypto.subtle.decrypt(
527→   527→        { name: 'AES-GCM', iv }, cryptoKey, encryptedBytes
528→   528→      );
529→   529→
530→   530→      return new Uint8Array(plaintext);
531→   531→    }
532→   532→
533→   533→    // =========================================================================
534→   534→    // Crypto: AES-256-CTR File Decrypt
535→   535→    // =========================================================================
536→   536→    async function decryptFileCtr(encryptedBytes, fileKey, fileIvHex) {
537→   537→      const iv = hexToBytes(fileIvHex); // 16 bytes (8-byte nonce + 8-byte counter)
538→   538→
539→   539→      const cryptoKey = await crypto.subtle.importKey(
540→   540→        'raw', fileKey, { name: 'AES-CTR' }, false, ['decrypt']
541→   541→      );
542→   542→      const plaintext = await crypto.subtle.decrypt(
543→   543→        { name: 'AES-CTR', counter: iv, length: 64 }, cryptoKey, encryptedBytes
544→   544→      );
545→   545→
546→   546→      return new Uint8Array(plaintext);
547→   547→    }
548→   548→
549→   549→    /**
550→   550→     * Decrypt file content using the appropriate mode (GCM or CTR).
551→   551→     * encryptionMode defaults to 'GCM' when not specified (backward compat).
552→   552→     */
553→   553→    async function decryptFile(encryptedBytes, fileKey, fileIvHex, encryptionMode) {
554→   554→      const mode = (encryptionMode || 'GCM').toUpperCase();
555→   555→      if (mode === 'CTR') {
556→   556→        return decryptFileCtr(encryptedBytes, fileKey, fileIvHex);
557→   557→      }
558→   558→      return decryptFileGcm(encryptedBytes, fileKey, fileIvHex);
559→   559→    }
560→   560→
561→   561→    // =========================================================================
562→   562→    // Crypto: HKDF File IPNS Derivation (v2 per-file metadata)
563→   563→    // =========================================================================
564→   564→    const FILE_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');
565→   565→
566→   566→    /**
567→   567→     * Derive a file's IPNS name from user's private key and fileId using HKDF.
568→   568→     * Matches the derivation in @cipherbox/crypto deriveFileIpnsKeypair.
569→   569→     *
570→   570→     * Path: secp256k1 privateKey -> HKDF-SHA256 -> 32-byte Ed25519 seed
571→   571→     *       -> Ed25519 public key -> IPNS name (k51...)
572→   572→     */
573→   573→    async function deriveFileIpnsName(userPrivateKey, fileId) {
574→   574→      const info = new TextEncoder().encode(`cipherbox-file-ipns-v1:${fileId}`);
575→   575→
576→   576→      // 1. HKDF-SHA256 to derive 32-byte Ed25519 seed
577→   577→      const keyMaterial = await crypto.subtle.importKey(
578→   578→        'raw', userPrivateKey, 'HKDF', false, ['deriveBits']
579→   579→      );
580→   580→      const derivedBits = await crypto.subtle.deriveBits(
581→   581→        { name: 'HKDF', hash: 'SHA-256', salt: FILE_HKDF_SALT, info },
582→   582→        keyMaterial, 256
583→   583→      );
584→   584→      const ed25519Seed = new Uint8Array(derivedBits);
585→   585→
586→   586→      // 2. Derive Ed25519 public key from seed
587→   587→      const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
588→   588→
589→   589→      // 3. Derive IPNS name from Ed25519 public key
590→   590→      return ed25519PublicKeyToIpnsName(ed25519PublicKey);
591→   591→    }
592→   592→
593→   593→    /**
594→   594→     * Convert an Ed25519 public key to an IPNS name (k51... base36 CIDv1).
595→   595→     *
596→   596→     * CID structure:
597→   597→     *   0x01 (CIDv1) + 0x72 (libp2p-key codec) + multihash
598→   598→     * Multihash:
599→   599→     *   0x00 (identity hash) + 0x24 (36 bytes digest length) + digest

  1→//! Tauri IPC commands for the desktop auth flow.
  2→//!
  3→//! These commands are invoked from the webview (TypeScript) via Tauri's
  4→//! `invoke()` API. They handle authentication, vault key decryption,
  5→//! Keychain storage, and logout.
  6→
  7→use std::sync::atomic::{AtomicU32, Ordering};
  8→use std::sync::Arc;
  9→use tauri::{Manager, State};
 10→
 11→/// Counter for unique OAuth popup window labels (shared with tray handler).
 12→static POPUP_COUNTER: AtomicU32 = AtomicU32::new(0);
 13→
 14→use zeroize::Zeroizing;
 15→
 16→use crate::api::{auth, types};
 17→use crate::crypto;
 18→use crate::state::AppState;
