600→   600→     * Digest (protobuf-encoded Ed25519 public key):
601→   601→     *   0x08 0x01 (field 1: KeyType = Ed25519)
602→   602→     *   0x12 0x20 (field 2: Data, 32 bytes)
603→   603→     *   + 32 bytes public key
604→   604→     */
605→   605→    function ed25519PublicKeyToIpnsName(publicKey) {
606→   606→      // Build CID bytes: version(1) + codec(0x72) + identity-multihash(protobuf key)
607→   607→      const cidBytes = new Uint8Array(40); // 2 + 2 + 4 + 32
608→   608→      cidBytes[0] = 0x01; // CIDv1
609→   609→      cidBytes[1] = 0x72; // libp2p-key multicodec
610→   610→      cidBytes[2] = 0x00; // identity multihash function code
611→   611→      cidBytes[3] = 0x24; // digest length = 36 bytes
612→   612→      // Protobuf: field 1 (KeyType) = Ed25519 = 1
613→   613→      cidBytes[4] = 0x08;
614→   614→      cidBytes[5] = 0x01;
615→   615→      // Protobuf: field 2 (Data) = length-delimited, 32 bytes
616→   616→      cidBytes[6] = 0x12;
617→   617→      cidBytes[7] = 0x20;
618→   618→      // Ed25519 public key bytes
619→   619→      cidBytes.set(publicKey, 8);
620→   620→
621→   621→      // Encode as base36lower with 'k' multibase prefix
622→   622→      return base36Encode(cidBytes);
623→   623→    }
624→   624→
625→   625→    /**
626→   626→     * Base36 encode bytes with 'k' multibase prefix (base36lower).
627→   627→     * Encodes as a big-endian unsigned integer in base36.
628→   628→     */
629→   629→    function base36Encode(bytes) {
630→   630→      const ALPHABET = 'REDACTED';
631→   631→
632→   632→      // Convert bytes to a BigInt (big-endian unsigned)
633→   633→      let n = 0n;
634→   634→      for (const b of bytes) {
635→   635→        n = (n << 8n) | BigInt(b);
636→   636→      }
637→   637→
638→   638→      // Convert to base36
639→   639→      if (n === 0n) return 'k0';
640→   640→      const digits = [];
641→   641→      while (n > 0n) {
642→   642→        digits.push(ALPHABET[Number(n % 36n)]);
643→   643→        n = n / 36n;
644→   644→      }
645→   645→
646→   646→      // Count leading zero bytes for zero-padding
647→   647→      let leadingZeros = 0;
648→   648→      for (const b of bytes) {
649→   649→        if (b === 0) leadingZeros++;
650→   650→        else break;
651→   651→      }
652→   652→      for (let i = 0; i < leadingZeros; i++) {
653→   653→        digits.push('0');
654→   654→      }
655→   655→
656→   656→      digits.reverse();
657→   657→      return 'k' + digits.join('');
658→   658→    }
