661→   661→    // Crypto: Decrypt File Metadata (v2 per-file IPNS records)
662→   662→    // =========================================================================
663→   663→    /**
664→   664→     * Decrypt per-file metadata. Same format as folder metadata:
665→   665→     * { iv: "hex", data: "base64" } encrypted with parent folderKey (AES-256-GCM).
666→   666→     */
667→   667→    async function decryptFileMetadata(encryptedJson, folderKey) {
668→   668→      const iv = hexToBytes(encryptedJson.iv);
669→   669→      const ciphertext = base64ToBytes(encryptedJson.data);
670→   670→
671→   671→      const cryptoKey = await crypto.subtle.importKey(
672→   672→        'raw', folderKey, { name: 'AES-GCM' }, false, ['decrypt']
673→   673→      );
674→   674→      const plaintext = await crypto.subtle.decrypt(
675→   675→        { name: 'AES-GCM', iv }, cryptoKey, ciphertext
676→   676→      );
677→   677→
678→   678→      return JSON.parse(new TextDecoder().decode(plaintext));
679→   679→    }
