681→   681→    // =========================================================================
682→   682→    // IPNS Resolution
683→   683→    // =========================================================================
684→   684→    async function resolveIpns(ipnsName, gatewayUrl) {
685→   685→      const maxRetries = 3;
686→   686→
687→   687→      // Primary: Delegated routing API
688→   688→      for (let attempt = 0; attempt < maxRetries; attempt++) {
689→   689→        try {
690→   690→          const url = `${gatewayUrl}/routing/v1/ipns/${ipnsName}`;
691→   691→          const resp = await fetch(url, {
692→   692→            headers: { 'Accept': 'application/vnd.ipfs.ipns-record' }
693→   693→          });
694→   694→
695→   695→          if (resp.ok) {
696→   696→            // The delegated routing API can return the IPNS record in different formats
697→   697→            // Try JSON first (application/json), then raw record
698→   698→            const contentType = resp.headers.get('Content-Type') || '';
699→   699→
700→   700→            if (contentType.includes('application/json')) {
701→   701→              const json = await resp.json();
702→   702→              // Extract CID from the record value
703→   703→              if (json.record && json.record.value) {
704→   704→                return extractCidFromValue(json.record.value);
705→   705→              }
706→   706→              if (json.value) {
707→   707→                return extractCidFromValue(json.value);
708→   708→              }
709→   709→            }
710→   710→
711→   711→            // For vnd.ipfs.ipns-record, the response is a binary IPNS record
712→   712→            // We need to parse the CBOR/protobuf to extract the Value field
713→   713→            const recordBytes = new Uint8Array(await resp.arrayBuffer());
714→   714→            const cid = extractCidFromIpnsRecord(recordBytes);
715→   715→            if (cid) return cid;
716→   716→          }
717→   717→        } catch (e) {
718→   718→          if (attempt < maxRetries - 1) {
719→   719→            await sleep(1000 * Math.pow(2, attempt));
720→   720→            continue;
721→   721→          }
722→   722→        }
723→   723→      }
724→   724→
725→   725→      // Fallback: ipfs.io name resolve API
726→   726→      for (let attempt = 0; attempt < maxRetries; attempt++) {
727→   727→        try {
728→   728→          const url = `https://ipfs.io/api/v0/name/resolve?arg=${ipnsName}`;
729→   729→          const resp = await fetch(url);
730→   730→          if (resp.ok) {
731→   731→            const json = await resp.json();
732→   732→            if (json.Path) {
733→   733→              return extractCidFromValue(json.Path);
734→   734→            }
735→   735→          }
736→   736→        } catch (e) {
737→   737→          if (attempt < maxRetries - 1) {
738→   738→            await sleep(1000 * Math.pow(2, attempt));
739→   739→            continue;
740→   740→          }
741→   741→        }
742→   742→      }
743→   743→
744→   744→      throw new Error(`Failed to resolve IPNS name: ${truncate(ipnsName, 20)}`);
745→   745→    }
746→   746→
747→   747→    function extractCidFromValue(value) {
748→   748→      // Value is typically "/ipfs/bafy..." - extract the CID
749→   749→      if (typeof value === 'string') {
750→   750→        if (value.startsWith('/ipfs/')) return value.slice(6);
751→   751→        return value;
752→   752→      }
753→   753→      // If it's bytes (from CBOR), decode as string
754→   754→      if (value instanceof Uint8Array) {
755→   755→        const str = new TextDecoder().decode(value);
756→   756→        if (str.startsWith('/ipfs/')) return str.slice(6);
757→   757→        return str;
758→   758→      }
759→   759→      throw new Error('Unexpected IPNS value format');
760→   760→    }
761→   761→
762→   762→    function extractCidFromIpnsRecord(recordBytes) {
763→   763→      // IPNS records are protobuf-encoded.
764→   764→      // The Value field is field number 2 (wire type 2 = length-delimited).
765→   765→      // We need to find field 2 in the protobuf.
766→   766→      try {
767→   767→        let offset = 0;
768→   768→        while (offset < recordBytes.length) {
769→   769→          const fieldByte = recordBytes[offset];
770→   770→          const fieldNumber = fieldByte >> 3;
771→   771→          const wireType = fieldByte & 0x07;
772→   772→
773→   773→          offset++;
774→   774→
775→   775→          if (wireType === 2) {
776→   776→            // Length-delimited
777→   777→            let length = 0;
778→   778→            let shift = 0;
779→   779→            while (offset < recordBytes.length) {
780→   780→              const b = recordBytes[offset++];
781→   781→              length |= (b & 0x7f) << shift;
782→   782→              if ((b & 0x80) === 0) break;
783→   783→              shift += 7;
784→   784→            }
785→   785→
786→   786→            if (fieldNumber === 2) {
787→   787→              // Value field - this is the IPFS path
788→   788→              const valueBytes = recordBytes.slice(offset, offset + length);
789→   789→              const value = new TextDecoder().decode(valueBytes);
790→   790→              return extractCidFromValue(value);
791→   791→            }
792→   792→
793→   793→            offset += length;
794→   794→          } else if (wireType === 0) {
795→   795→            // Varint - skip
796→   796→            while (offset < recordBytes.length && (recordBytes[offset] & 0x80) !== 0) offset++;
797→   797→            offset++;
798→   798→          } else {
799→   799→            // Unknown wire type, bail

800→   800→            break;
801→   801→          }
802→   802→        }
803→   803→      } catch (e) {
804→   804→        // Failed to parse protobuf
805→   805→      }
806→   806→      return null;
807→   807→    }
