809→   809→    // =========================================================================
810→   810→    // IPFS Content Fetch
811→   811→    // =========================================================================
812→   812→    async function fetchFromIpfs(cid, ipfsGatewayUrl) {
813→   813→      const maxRetries = 3;
814→   814→
815→   815→      for (let attempt = 0; attempt < maxRetries; attempt++) {
816→   816→        try {
817→   817→          const url = `${ipfsGatewayUrl}/ipfs/${cid}`;
818→   818→          const resp = await fetch(url);
819→   819→          if (resp.ok) {
820→   820→            return new Uint8Array(await resp.arrayBuffer());
821→   821→          }
822→   822→          if (resp.status === 404) {
823→   823→            throw new Error(`Content not found on IPFS: ${truncate(cid, 20)}`);
824→   824→          }
825→   825→        } catch (e) {
826→   826→          if (e.message.includes('not found')) throw e;
827→   827→          if (attempt < maxRetries - 1) {
828→   828→            await sleep(1000 * Math.pow(2, attempt));
829→   829→            continue;
830→   830→          }
831→   831→          throw new Error(`Failed to fetch from IPFS: ${truncate(cid, 20)}`);
832→   832→        }
833→   833→      }
834→   834→    }
