840→   840→    // =========================================================================
841→   841→    // Recursive Folder Recovery
842→   842→    // =========================================================================
843→   843→    async function recoverFolder(ipnsName, folderKey, path, gatewayConfig) {
844→   844→      // 1. Resolve IPNS name -> CID
845→   845→      log(`Resolving IPNS: ${truncate(ipnsName, 30)}...`, 'info');
846→   846→      const cid = await resolveIpns(ipnsName, gatewayConfig.ipnsGateway);
847→   847→      log(`  Resolved to CID: ${truncate(cid, 40)}`, 'info');
848→   848→
849→   849→      // 2. Fetch encrypted metadata
850→   850→      log(`Fetching metadata for ${path || '/'}...`, 'info');
851→   851→      const metadataBytes = await fetchFromIpfs(cid, gatewayConfig.ipfsGateway);
852→   852→
853→   853→      // 3. Parse as JSON (encrypted metadata format)
854→   854→      let encryptedMeta;
855→   855→      try {
856→   856→        encryptedMeta = JSON.parse(new TextDecoder().decode(metadataBytes));
857→   857→      } catch (e) {
858→   858→        throw new Error(`Failed to parse metadata JSON for ${path || '/'}`);
859→   859→      }
860→   860→
861→   861→      // 4. Decrypt metadata
862→   862→      log(`Decrypting metadata for ${path || '/'}...`, 'info');
863→   863→      const metadata = await decryptFolderMetadata(encryptedMeta, folderKey);
864→   864→
865→   865→      if (!metadata.children || !Array.isArray(metadata.children)) {
866→   866→        log(`  No children in ${path || '/'}`, 'info');
867→   867→        return;
868→   868→      }
869→   869→
870→   870→      // Reject non-v2 metadata
871→   871→      if (metadata.version !== 'v2') {
872→   872→        log(`  ERROR: Unsupported metadata version "${metadata.version}" for ${path || '/'} (only v2 supported). Skipping folder.`, 'error');
873→   873→        errorCount++;
874→   874→        return;
875→   875→      }
876→   876→
877→   877→      log(`  Found ${metadata.children.length} items in ${path || '/'}`, 'success');
878→   878→
879→   879→      // 5. Process each child
880→   880→      for (const child of metadata.children) {
881→   881→        if (child.type === 'folder') {
882→   882→          try {
883→   883→            // ECIES-decrypt subfolder keys
884→   884→            log(`Decrypting keys for folder: ${child.name}`, 'info');
885→   885→            const subFolderKey = await eciesDecrypt(privateKeyBytes, child.folderKeyEncrypted);
886→   886→
887→   887→            // We decrypt the IPNS private key for completeness but only need the name
888→   888→            // (ipnsPrivateKey is 64-byte libp2p format: seed||pubkey)
889→   889→            const subPath = path ? `${path}/${child.name}` : child.name;
890→   890→
891→   891→            // Recurse into subfolder
892→   892→            await recoverFolder(child.ipnsName, subFolderKey, subPath, gatewayConfig);
893→   893→          } catch (e) {
894→   894→            log(`  ERROR recovering folder "${child.name}": ${e.message}`, 'error');
895→   895→            errorCount++;
896→   896→          }
897→   897→        } else if (child.type === 'file') {
898→   898→          // Validate FilePointer has required fileMetaIpnsName
899→   899→          if (!child.fileMetaIpnsName) {
900→   900→            log(`  ERROR: Invalid file child "${child.name}": missing fileMetaIpnsName (v1 format not supported)`, 'error');
901→   901→            errorCount++;
902→   902→            continue;
903→   903→          }
904→   904→
905→   905→          // ── FilePointer: resolve per-file IPNS to get file metadata ──
906→   906→          try {
907→   907→            const filePath = path ? `${path}/${child.name}` : child.name;
908→   908→            log(`Resolving file IPNS: ${child.name}...`, 'info');
909→   909→
910→   910→            const fileIpnsName = child.fileMetaIpnsName;
911→   911→
912→   912→            // a. Resolve file IPNS to get file metadata CID
913→   913→            let fileMetaCid;
914→   914→            try {
915→   915→              fileMetaCid = await resolveIpns(fileIpnsName, gatewayConfig.ipnsGateway);
916→   916→            } catch (resolveErr) {
917→   917→              log(`  WARNING: File IPNS record may have expired for "${child.name}". ` +
918→   918→                  `IPNS name: ${truncate(fileIpnsName, 30)}. ` +
919→   919→                  `File content CID is not recoverable via IPNS.`, 'warn');
920→   920→              ipnsFailures.push({ name: child.name, ipnsName: fileIpnsName });
921→   921→              errorCount++;
922→   922→              continue;
923→   923→            }
924→   924→
925→   925→            log(`  File metadata CID: ${truncate(fileMetaCid, 40)}`, 'info');
926→   926→
927→   927→            // b. Fetch encrypted file metadata from IPFS
928→   928→            const encFileMetaBytes = await fetchFromIpfs(fileMetaCid, gatewayConfig.ipfsGateway);
929→   929→            const encFileMeta = JSON.parse(new TextDecoder().decode(encFileMetaBytes));
930→   930→
931→   931→            // c. Decrypt file metadata with parent's folderKey
932→   932→            const fileMeta = await decryptFileMetadata(encFileMeta, folderKey);
933→   933→
934→   934→            // d. Extract file details from decrypted metadata
935→   935→            const { cid: contentCid, fileKeyEncrypted, fileIv, size, encryptionMode } = fileMeta;
936→   936→
937→   937→            log(`Downloading: ${filePath}... (${formatSize(size || 0)})`, 'info');
938→   938→
939→   939→            // e. ECIES-decrypt file key
940→   940→            const fileKey = await eciesDecrypt(privateKeyBytes, fileKeyEncrypted);
941→   941→
942→   942→            // f. Fetch encrypted file from IPFS
943→   943→            const encryptedFile = await fetchFromIpfs(contentCid, gatewayConfig.ipfsGateway);
944→   944→
945→   945→            // g. Decrypt file content (using encryptionMode, defaults to GCM)
946→   946→            const decryptedFile = await decryptFile(encryptedFile, fileKey, fileIv, encryptionMode);
947→   947→
948→   948→            // Store for zip
949→   949→            recoveredFiles.push({ path: filePath, data: decryptedFile });
950→   950→            fileCount++;
951→   951→
952→   952→            log(`  Decrypted: ${filePath} (${formatSize(decryptedFile.length)})`, 'success');
953→   953→
954→   954→            // h. Process past versions if present
955→   955→            if (Array.isArray(fileMeta.versions) && fileMeta.versions.length > 0) {
956→   956→              log(`  Past versions: ${fileMeta.versions.length}`, 'info');
957→   957→
958→   958→              for (let vi = 0; vi < fileMeta.versions.length; vi++) {
959→   959→                const ver = fileMeta.versions[vi];
960→   960→                const verDate = new Date(ver.timestamp).toISOString().slice(0, 19).replace('T', ' ');
961→   961→                const verLabel = `v${fileMeta.versions.length - vi}`;
962→   962→
963→   963→                try {
964→   964→                  log(`  Downloading ${verLabel} (${verDate}, ${formatSize(ver.size || 0)}, ${ver.encryptionMode || 'GCM'})...`, 'info');
965→   965→
966→   966→                  // Decrypt version's file key
967→   967→                  const verFileKey = await eciesDecrypt(privateKeyBytes, ver.fileKeyEncrypted);
968→   968→
969→   969→                  // Fetch version's encrypted content from IPFS
970→   970→                  const verEncrypted = await fetchFromIpfs(ver.cid, gatewayConfig.ipfsGateway);
971→   971→
972→   972→                  // Decrypt version content with appropriate mode
973→   973→                  const verDecrypted = await decryptFile(verEncrypted, verFileKey, ver.fileIv, ver.encryptionMode);
